const validate  = $('Code: Validate').first().json;
const allDates  = (validate.dates || '').split(',').filter(Boolean).sort();
const clashRow  = $input.first().json;
const clashed   = new Set((clashRow.clashed_dates || []).map(d => String(d).trim().slice(0, 10)));

const fmtDate = d => {
  const dt = new Date(d + 'T12:00:00');
  return dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
};

// ── No clashes ────────────────────────────────────────────────────────────
if (clashed.size === 0) {
  return [{ json: {
    filtered_dates: validate.dates || '',
    dates_count:    allDates.length,
    has_conflict:   false,
    blocked:        false,
    warning:        null
  }}];
}

// ── Hard block: first session date is unavailable — reject the whole request ──
if (allDates.length > 0 && clashed.has(allDates[0])) {
  return [{ json: {
    filtered_dates:      '',
    dates_count:         0,
    has_conflict:        true,
    blocked:             true,
    first_conflict_date: allDates[0],
    warning: 'The first session date (' + fmtDate(allDates[0]) + ') is already taken for this room at this time. Please choose a different start date or room.'
  }}];
}

// ── Soft block: later dates clash — exclude only those specific dates ──────
const safeDates    = allDates.filter(d => !clashed.has(d));
const removedDates = allDates.filter(d =>  clashed.has(d));

// Edge case: somehow all remaining dates clashed
if (safeDates.length === 0) {
  return [{ json: {
    filtered_dates:      '',
    dates_count:         0,
    has_conflict:        true,
    blocked:             true,
    first_conflict_date: removedDates[0] || null,
    removed_dates:       removedDates,
    warning: 'All ' + allDates.length + ' requested session dates are already taken for this room at this time. Please choose a different time or room.'
  }}];
}

// Build a readable list of excluded dates
const fmtList = removedDates.map(fmtDate);
let removedMsg;
if (fmtList.length === 1) {
  removedMsg = fmtList[0];
} else if (fmtList.length <= 4) {
  removedMsg = fmtList.slice(0, -1).join(', ') + ' and ' + fmtList[fmtList.length - 1];
} else {
  removedMsg = fmtList.slice(0, 3).join(', ') + ', and ' + (fmtList.length - 3) + ' more';
}

return [{ json: {
  filtered_dates:      safeDates.join(','),
  dates_count:         safeDates.length,
  has_conflict:        true,
  blocked:             false,
  first_conflict_date: removedDates[0],
  clashed_count:       clashed.size,
  removed_dates:       removedDates,
  warning: safeDates.length + ' session(s) booked. ' + removedDates.length + ' date(s) excluded due to conflicts: ' + removedMsg + '.'
}}];

